        ) : null}

        {isGenerating ? <AgentProgress stages={agentProgress} /> : null}

        {plan ? (
          <>
            <RecoveryDashboard plan={plan} />
            <section className="chat-section" aria-labelledby="recovery-chat-heading">
              <h2 id="recovery-chat-heading">Recovery Chat</h2>

